import{_ as a,o as t,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/faq/index.md","filePath":"v1/en/faq/index.md"}'),o={name:"v1/en/faq/index.md"};function s(n,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>This page collects the most common questions and quick fixes when using Expense Tracker: Koala (“Koala”). If something goes wrong, start here.</p><hr><h2 id="bill-import" tabindex="-1">Bill Import <a class="header-anchor" href="#bill-import" aria-label="Permalink to &quot;Bill Import&quot;">​</a></h2><h3 id="q-what-bill-sources-are-supported-which-file-formats-can-i-import" tabindex="-1">Q: What bill sources are supported? Which file formats can I import? <a class="header-anchor" href="#q-what-bill-sources-are-supported-which-file-formats-can-i-import" aria-label="Permalink to &quot;Q: What bill sources are supported? Which file formats can I import?&quot;">​</a></h3><p><strong>A:</strong> Koala currently supports 5 sources:</p><ul><li><strong>Template import</strong>: CSV (<code>.csv</code>)</li><li><strong>WeChat bills</strong>: CSV / Excel (<code>.csv</code> / <code>.xlsx</code> / <code>.xls</code>)</li><li><strong>Alipay bills</strong>: CSV (<code>.csv</code>)</li><li><strong>Pixiu</strong>: CSV (<code>.csv</code>)</li><li><strong>iCost</strong>: Excel (<code>.xlsx</code> / <code>.xls</code>) — iCost CSV is not supported</li></ul><p>Related guides:</p><ul><li><a href="./../guide/01-template-bill-import-guide">Template Bill Import Guide</a></li><li><a href="./../guide/02-wechat-bill-import-guide">WeChat Bill Import Guide</a></li><li><a href="./../guide/03-alipay-bill-import-guide">Alipay Bill Import Guide</a></li><li><a href="./../guide/07-pixiu-bill-import-guide">Pixiu Bill Import Guide</a></li><li><a href="./../guide/08-icost-bill-import-guide">iCost Bill Import Guide</a></li></ul><h3 id="q-why-do-i-see-parse-failed-open-failed-header-not-found" tabindex="-1">Q: Why do I see “Parse failed / Open failed / Header not found”? <a class="header-anchor" href="#q-why-do-i-see-parse-failed-open-failed-header-not-found" aria-label="Permalink to &quot;Q: Why do I see “Parse failed / Open failed / Header not found”?&quot;">​</a></h3><p><strong>A:</strong> In most cases, it’s one of the following (from most common to less common):</p><ol><li><strong>Wrong import source selected</strong>: for example, parsing a WeChat file as Template/Alipay may fail immediately or shift fields.</li><li><strong>The file was edited</strong>: opening in Excel/WPS and renaming headers, deleting/adding columns, or changing the delimiter is a very common cause.</li><li><strong>Unsupported export format</strong>: for example, exporting iCost as CSV or using a non-standard Alipay export.</li><li><strong>Corrupted/incomplete file</strong>: interrupted downloads, broken attachments, or content lost during sharing.</li><li><strong>File too large</strong>: very large files may be slow to parse or fail; export by smaller time ranges and import in batches.</li></ol><p>Best practice: re-export a fresh file from the original app (do not edit it), make sure the import source in Koala matches, then parse again.</p><h3 id="q-why-is-the-imported-amount-0-or-incorrect" tabindex="-1">Q: Why is the imported amount 0 or incorrect? <a class="header-anchor" href="#q-why-is-the-imported-amount-0-or-incorrect" aria-label="Permalink to &quot;Q: Why is the imported amount 0 or incorrect?&quot;">​</a></h3><p><strong>A:</strong> Common causes:</p><ul><li><strong>Income/expense detection is wrong</strong>: some sources use keywords to decide which amount column to read (e.g. Pixiu inflow/outflow). If the “type” field is abnormal, Koala may read the wrong column.</li><li><strong>Amount field is empty or contains unexpected characters</strong>: spaces or invisible characters can cause parsing issues.</li><li><strong>Thousands separators / signs</strong>: exports may include <code>+/-</code> or commas. Koala usually handles them, but “re-saved” files may end up in an incompatible format.</li></ul><p>Recommendation: on the preview page, verify <strong>type (income/expense)</strong> and <strong>amount</strong> first. If it looks off, re-export the original file.</p><h3 id="q-categories-accounts-tags-don-t-match-after-import-what-should-i-do" tabindex="-1">Q: Categories/accounts/tags don’t match after import. What should I do? <a class="header-anchor" href="#q-categories-accounts-tags-don-t-match-after-import-what-should-i-do" aria-label="Permalink to &quot;Q: Categories/accounts/tags don’t match after import. What should I do?&quot;">​</a></h3><p><strong>A:</strong> Koala tries its best to match automatically, but different apps use different category structures, so 100% accuracy can’t be guaranteed.</p><ul><li><strong>Categories</strong>: adjust per record in the preview page; for better matching, create categories in Koala with the same names as the export file, then parse again.</li><li><strong>Accounts</strong>: usually matched by account name/payment method; if not found, Koala may create a new account. Create common accounts ahead of time, and bulk-fix them in the preview page if needed.</li><li><strong>Tags</strong>: matched by tag name; missing tags may be created. Review for unwanted tag names (extra spaces/symbols).</li></ul><h3 id="q-does-koala-deduplicate-imports-automatically-what-happens-if-i-import-the-same-file-twice" tabindex="-1">Q: Does Koala deduplicate imports automatically? What happens if I import the same file twice? <a class="header-anchor" href="#q-does-koala-deduplicate-imports-automatically-what-happens-if-i-import-the-same-file-twice" aria-label="Permalink to &quot;Q: Does Koala deduplicate imports automatically? What happens if I import the same file twice?&quot;">​</a></h3><p><strong>A:</strong> Strategies vary by source, but the safest assumption is: <strong>no automatic deduplication</strong>.</p><ul><li>Best practice: avoid importing the same file or the same time range multiple times; if you import in batches, keep time ranges non-overlapping.</li><li>If duplicates were created: filter by time range in the bill list and delete duplicates manually.</li></ul><h3 id="q-how-are-refunds-transfers-red-packets-handled" tabindex="-1">Q: How are refunds / transfers / red packets handled? <a class="header-anchor" href="#q-how-are-refunds-transfers-red-packets-handled" aria-label="Permalink to &quot;Q: How are refunds / transfers / red packets handled?&quot;">​</a></h3><p><strong>A:</strong> These records vary a lot across platforms. After import, it’s recommended to:</p><ul><li>Check <strong>type (income/expense)</strong> and <strong>the sign of the amount</strong> in the preview page</li><li>Adjust categories when needed (e.g. map “Refund” to a refund/other-income category)</li><li>Use the note field to trace details (status/order IDs are often appended into the note)</li></ul><h3 id="q-how-much-should-i-import-at-once-import-is-slow" tabindex="-1">Q: How much should I import at once? Import is slow. <a class="header-anchor" href="#q-how-much-should-i-import-at-once-import-is-slow" aria-label="Permalink to &quot;Q: How much should I import at once? Import is slow.&quot;">​</a></h3><p><strong>A:</strong> Split by time range:</p><ul><li>For WeChat/Alipay, exporting up to <strong>3 months</strong> per file is usually more stable and faster.</li><li>For large histories, export multiple files and import them one by one.</li><li>Keep Koala in the foreground during import to reduce interruptions.</li></ul><hr><h2 id="multiple-ledgers" tabindex="-1">Multiple Ledgers <a class="header-anchor" href="#multiple-ledgers" aria-label="Permalink to &quot;Multiple Ledgers&quot;">​</a></h2><h3 id="q-my-data-disappeared-after-switching-ledgers" tabindex="-1">Q: My data “disappeared” after switching ledgers. <a class="header-anchor" href="#q-my-data-disappeared-after-switching-ledgers" aria-label="Permalink to &quot;Q: My data “disappeared” after switching ledgers.&quot;">​</a></h3><p><strong>A:</strong> Most likely you switched to a different ledger. Bills, categories, tags, and statistics are isolated per ledger.</p><p>Recommendation: open <strong>Ledger management</strong> to confirm the current ledger, then check the bill list again.</p><h3 id="q-what-data-is-per-ledger-and-what-is-shared" tabindex="-1">Q: What data is per-ledger and what is shared? <a class="header-anchor" href="#q-what-data-is-per-ledger-and-what-is-shared" aria-label="Permalink to &quot;Q: What data is per-ledger and what is shared?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>Per-ledger</strong>: bills, categories, tags, statistics</li><li><strong>Shared on the device</strong>: accounts (the same account can be used across ledgers)</li></ul><h3 id="q-what-happens-when-i-delete-a-ledger-can-i-restore-it" tabindex="-1">Q: What happens when I delete a ledger? Can I restore it? <a class="header-anchor" href="#q-what-happens-when-i-delete-a-ledger-can-i-restore-it" aria-label="Permalink to &quot;Q: What happens when I delete a ledger? Can I restore it?&quot;">​</a></h3><p><strong>A:</strong> Deleting a ledger removes it from this device. If cloud sync is enabled, the deletion will also be applied to the cloud after a sync. It cannot be restored inside the app, so please double-check before deleting.</p><hr><h2 id="currency-exchange-rates" tabindex="-1">Currency &amp; Exchange Rates <a class="header-anchor" href="#currency-exchange-rates" aria-label="Permalink to &quot;Currency &amp; Exchange Rates&quot;">​</a></h2><h3 id="q-what-is-the-base-currency-ledger-currency-what-does-it-affect" tabindex="-1">Q: What is the base currency / ledger currency? What does it affect? <a class="header-anchor" href="#q-what-is-the-base-currency-ledger-currency-what-does-it-affect" aria-label="Permalink to &quot;Q: What is the base currency / ledger currency? What does it affect?&quot;">​</a></h3><p><strong>A:</strong> The base currency (ledger currency) is the main display currency for the current ledger. It affects:</p><ul><li>Amount display (converted for display)</li><li>Overview and statistics calculations</li><li>Exchange-rate list (shown relative to the base currency)</li></ul><h3 id="q-why-did-the-converted-amounts-of-old-bills-change-after-refreshing-rates" tabindex="-1">Q: Why did the converted amounts of old bills change after refreshing rates? <a class="header-anchor" href="#q-why-did-the-converted-amounts-of-old-bills-change-after-refreshing-rates" aria-label="Permalink to &quot;Q: Why did the converted amounts of old bills change after refreshing rates?&quot;">​</a></h3><p><strong>A:</strong> Koala uses the <strong>current exchange rate</strong> for conversion display. After refreshing rates or changing the base currency, the <strong>converted display</strong> of historical bills may change, but the <strong>original transaction amount</strong> does not.</p><h3 id="q-what-happens-when-i-m-offline-what-if-rate-refresh-fails" tabindex="-1">Q: What happens when I’m offline? What if rate refresh fails? <a class="header-anchor" href="#q-what-happens-when-i-m-offline-what-if-rate-refresh-fails" aria-label="Permalink to &quot;Q: What happens when I’m offline? What if rate refresh fails?&quot;">​</a></h3><p><strong>A:</strong> Offline, Koala will try to use the last saved rates. If refresh fails:</p><ol><li>Check your network connection</li><li>Try again later</li><li>If you edited rates manually, verify the values are what you expect</li></ol><hr><h2 id="cloud-backup-sync" tabindex="-1">Cloud Backup &amp; Sync <a class="header-anchor" href="#cloud-backup-sync" aria-label="Permalink to &quot;Cloud Backup &amp; Sync&quot;">​</a></h2><h3 id="q-do-i-need-to-sign-in-for-cloud-backup-which-sign-in-methods-are-supported" tabindex="-1">Q: Do I need to sign in for cloud backup? Which sign-in methods are supported? <a class="header-anchor" href="#q-do-i-need-to-sign-in-for-cloud-backup-which-sign-in-methods-are-supported" aria-label="Permalink to &quot;Q: Do I need to sign in for cloud backup? Which sign-in methods are supported?&quot;">​</a></h3><p><strong>A:</strong> Yes. Koala currently supports <strong>Sign in with Apple</strong>. You can sign in via the user card at the top of the Settings page.</p><h3 id="q-what-data-is-synced-what-is-not-synced" tabindex="-1">Q: What data is synced? What is not synced? <a class="header-anchor" href="#q-what-data-is-synced-what-is-not-synced" aria-label="Permalink to &quot;Q: What data is synced? What is not synced?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>Synced</strong>: ledgers, bills, accounts, categories, tags</li><li><strong>Not synced</strong>: app settings (theme/language), cache, preferences</li></ul><h3 id="q-when-does-sync-happen-automatically-how-do-i-sync-manually" tabindex="-1">Q: When does sync happen automatically? How do I sync manually? <a class="header-anchor" href="#q-when-does-sync-happen-automatically-how-do-i-sync-manually" aria-label="Permalink to &quot;Q: When does sync happen automatically? How do I sync manually?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>Automatic</strong>: typically on app launch, after data changes, and when switching ledgers</li><li><strong>Manual</strong>: tap the cloud icon at the top-right of the Settings page</li></ul><p>During manual sync, keep the app in the foreground until it finishes.</p><h3 id="q-what-if-i-edit-the-same-record-on-multiple-devices" tabindex="-1">Q: What if I edit the same record on multiple devices? <a class="header-anchor" href="#q-what-if-i-edit-the-same-record-on-multiple-devices" aria-label="Permalink to &quot;Q: What if I edit the same record on multiple devices?&quot;">​</a></h3><p><strong>A:</strong> Koala tries to keep the newest change while also avoiding overwriting local edits that haven’t been uploaded yet. When using multiple devices, it’s best to let one device finish syncing before making large edits on another device.</p><h3 id="q-can-i-restore-my-data-after-reinstalling-or-switching-devices" tabindex="-1">Q: Can I restore my data after reinstalling or switching devices? <a class="header-anchor" href="#q-can-i-restore-my-data-after-reinstalling-or-switching-devices" aria-label="Permalink to &quot;Q: Can I restore my data after reinstalling or switching devices?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>Signed in and synced</strong>: reinstall and sign in with the same account, then wait for sync to restore data</li><li><strong>Not signed in</strong>: data is local-only, and uninstalling will remove it permanently</li></ul><hr><h2 id="membership-pricing" tabindex="-1">Membership &amp; Pricing <a class="header-anchor" href="#membership-pricing" aria-label="Permalink to &quot;Membership &amp; Pricing&quot;">​</a></h2><h3 id="q-why-isn-t-koala-offered-as-a-one-time-purchase" tabindex="-1">Q: Why isn’t Koala offered as a one-time purchase? <a class="header-anchor" href="#q-why-isn-t-koala-offered-as-a-one-time-purchase" aria-label="Permalink to &quot;Q: Why isn’t Koala offered as a one-time purchase?&quot;">​</a></h3><p><strong>A:</strong> Because I want Koala to be a long-term product that keeps improving, not a one-off transaction.</p><p>A membership model supports sustainable development: ongoing bug fixes, experience improvements, and continuous adaptation to OS updates and new devices, plus long-term investment in capabilities like sync, data safety, and performance. That way, you get an app that keeps getting better over time, instead of risking slow updates and unsustainable maintenance after a buyout.</p><hr><h2 id="feedback-support" tabindex="-1">Feedback &amp; Support <a class="header-anchor" href="#feedback-support" aria-label="Permalink to &quot;Feedback &amp; Support&quot;">​</a></h2><h3 id="q-what-should-i-include-when-reporting-an-issue" tabindex="-1">Q: What should I include when reporting an issue? <a class="header-anchor" href="#q-what-should-i-include-when-reporting-an-issue" aria-label="Permalink to &quot;Q: What should I include when reporting an issue?&quot;">​</a></h3><p><strong>A:</strong> The more complete the information, the easier it is to troubleshoot. Recommended:</p><ul><li>Import source (WeChat/Alipay/Pixiu/iCost/Template)</li><li>File format (CSV/Excel) and exported time range</li><li>Screenshot of the error message (if any)</li><li>What you already tried (re-exporting, changing source, changing file, etc.)</li></ul>',75)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
